private enum class V3Page { HOME, SCAN, RESULTS, HISTORY, PREMIUM, SETTINGS }
private enum class V3Mode(val label: String) { QUICK("Quick Recovery"), DEEP("Deep Recovery") }
private enum class V3Type(val label: String, val color: Color) { IMAGE("Images", Color(0xFFE85D75)), VIDEO("Videos", Color(0xFF4B82E8)), AUDIO("Audio", Color(0xFF8A63D2)), OTHER("Documents", Color(0xFFE09A32)) }
private enum class V3Sort { NAME, SIZE, DATE }
private data class V3File(val id: String, val name: String, val type: V3Type, val size: Long, val date: Long, val uri: Uri)
private data class V3Scan(val mode: String, val count: Int, val bytes: Long, val date: Long, val cancelled: Boolean = false)

private val v3Themes = listOf(
    Color(0xFF9A6B08) to Color(0xFFFFFBF4),
    Color(0xFF1769AA) to Color(0xFFF7FBFF),
    Color(0xFF147D64) to Color(0xFFF7FCF9),
    Color(0xFF7046A8) to Color(0xFFFCF8FF)
)
private val v3Shape = RoundedCornerShape(20.dp)
private fun Modifier.v3Card() = shadow(3.dp, v3Shape, false)

@Composable
fun RecoveryAppV3() {
    val context = LocalContext.current
    val prefs = remember { context.getSharedPreferences("rss_recovery_v3", 0) }
    var registered by remember { mutableStateOf(prefs.getBoolean("registered", false)) }
    var dark by remember { mutableStateOf(prefs.getBoolean("dark", false)) }
    var theme by remember { mutableIntStateOf(prefs.getInt("theme", 0).coerceIn(0, 3)) }
    var locked by remember { mutableStateOf(prefs.getBoolean("lock", false) && prefs.getString("pin", null) != null) }
    val primary = v3Themes[theme].first
    val surface = v3Themes[theme].second
    MaterialTheme(if (dark) darkColorScheme(primary = primary) else lightColorScheme(primary = primary, surface = surface)) {
        when {
            !registered -> V3Registration { name, email -> prefs.edit().putBoolean("registered", true).putString("name", name).putString("email", email).apply(); registered = true }
            locked -> V3Lock { pin -> if (pin == prefs.getString("pin", "")) locked = false }
            else -> V3Shell(prefs, dark, { dark = it; prefs.edit().putBoolean("dark", it).apply() }, theme, { theme = it; prefs.edit().putInt("theme", it).apply() }, { enabled -> locked = enabled; prefs.edit().putBoolean("lock", enabled).apply() })
        }
    }
}

@Composable private fun V3Registration(done: (String, String) -> Unit) {
    var name by remember { mutableStateOf("") }; var email by remember { mutableStateOf("") }
    Box(Modifier.fillMaxSize(), Alignment.Center) { Card(Modifier.fillMaxWidth().padding(22.dp).v3Card(), shape = RoundedCornerShape(28.dp)) { Column(Modifier.padding(24.dp)) {
        Icon(Icons.Default.Security, null, Modifier.size(54.dp), tint = MaterialTheme.colorScheme.primary); Spacer(Modifier.height(14.dp)); Text("Create your profile", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold); Spacer(Modifier.height(18.dp))
        OutlinedTextField(name, { name = it }, Modifier.fillMaxWidth(), label = { Text("Full name") }, singleLine = true); Spacer(Modifier.height(10.dp))
        OutlinedTextField(email, { email = it }, Modifier.fillMaxWidth(), label = { Text("Email address") }, singleLine = true, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email)); Spacer(Modifier.height(18.dp))
        Button({ done(name.trim(), email.trim()) }, Modifier.fillMaxWidth().height(52.dp), enabled = name.trim().length > 1 && email.contains("@")) { Text("Continue") }
    } } }
}

@Composable private fun V3Shell(prefs: android.content.SharedPreferences, dark: Boolean, setDark: (Boolean) -> Unit, theme: Int, setTheme: (Int) -> Unit, setLock: (Boolean) -> Unit) {
    var page by remember { mutableStateOf(V3Page.HOME) }; var drawer by remember { mutableStateOf(false) }; var mode by remember { mutableStateOf(V3Mode.QUICK) }; var files by remember { mutableStateOf(emptyList<V3File>()) }; var scans by remember { mutableStateOf(loadV3History(prefs)) }
    var destination by remember { mutableStateOf<Uri?>(null) }; var showDestination by remember { mutableStateOf(false) }
    val back = { if (drawer) drawer = false else page = V3Page.HOME }
    BackHandler(page != V3Page.HOME || drawer) { back() }
    if (showDestination) V3DestinationDialog({ destination = it; showDestination = false }, { showDestination = false })
    ModalNavigationDrawer(drawerState = rememberDrawerState(if (drawer) DrawerValue.Open else DrawerValue.Closed), drawerContent = {
        ModalDrawerSheet(Modifier.width(305.dp)) { Spacer(Modifier.height(20.dp)); Text("RSS Data Recovery", Modifier.padding(20.dp), fontWeight = FontWeight.Bold, style = MaterialTheme.typography.titleLarge)
            V3Drawer("Home", Icons.Default.Home, page == V3Page.HOME) { page = V3Page.HOME; drawer = false }; V3Drawer("Recovery", Icons.Default.Restore, page == V3Page.SCAN) { page = V3Page.SCAN; drawer = false }; V3Drawer("Results", Icons.Default.Folder, page == V3Page.RESULTS) { page = V3Page.RESULTS; drawer = false }; V3Drawer("Recovery history", Icons.Default.History, page == V3Page.HISTORY) { page = V3Page.HISTORY; drawer = false }; V3Drawer("Premium", Icons.Default.WorkspacePremium, page == V3Page.PREMIUM) { page = V3Page.PREMIUM; drawer = false }; V3Drawer("Settings", Icons.Default.Settings, page == V3Page.SETTINGS) { page = V3Page.SETTINGS; drawer = false }
            Spacer(Modifier.weight(1f)); HorizontalDivider(); V3Contact("+94 77 115 5504", Icons.Default.Phone) { dialV3(LocalContext.current, "+94771155504") }; V3Contact("rsscctvsolution@gmail.com", Icons.Default.Email) { openV3("mailto:rsscctvsolution@gmail.com") }; V3Contact("www.rsscctvsolution.eu.cc", Icons.Default.Language) { openV3("https://www.rsscctvsolution.eu.cc") }; Spacer(Modifier.height(14.dp))
        }
    }) {
        Scaffold(topBar = { TopAppBar(title = { Text(when(page) { V3Page.HOME -> "Home"; V3Page.SCAN -> mode.label; V3Page.RESULTS -> "Results"; V3Page.HISTORY -> "Recovery history"; V3Page.PREMIUM -> "Premium"; V3Page.SETTINGS -> "Settings" }) }, navigationIcon = { IconButton({ if (page == V3Page.HOME) drawer = true else back() }) { Icon(if (page == V3Page.HOME) Icons.Default.Menu else Icons.Default.ArrowBack, null) } }) }, bottomBar = { NavigationBar { NavigationBarItem(page == V3Page.HOME, { page = V3Page.HOME }, { Icon(Icons.Default.Home, null) }, label = { Text("Home") }); NavigationBarItem(page == V3Page.SCAN, { page = V3Page.SCAN }, { Icon(Icons.Default.Restore, null) }, label = { Text("Recover") }); NavigationBarItem(page == V3Page.RESULTS, { page = V3Page.RESULTS }, { Icon(Icons.Default.Folder, null) }, label = { Text("Results") }); NavigationBarItem(page == V3Page.SETTINGS, { page = V3Page.SETTINGS }, { Icon(Icons.Default.Settings, null) }, label = { Text("Settings") }) } }) { pad ->
            Box(Modifier.padding(pad).fillMaxSize()) { when(page) {
                V3Page.HOME -> V3Home({ mode = V3Mode.QUICK; page = V3Page.SCAN }, { mode = V3Mode.DEEP; page = V3Page.SCAN }, { page = V3Page.HISTORY })
                V3Page.SCAN -> V3Scan(mode, files) { result -> files = result; scans = loadV3History(prefs); page = V3Page.RESULTS }
                V3Page.RESULTS -> V3Results(files, destination, { showDestination = true }, { page = V3Page.PREMIUM })
                V3Page.HISTORY -> V3History(scans)
                V3Page.PREMIUM -> V3Premium()
                V3Page.SETTINGS -> V3Settings(dark, setDark, theme, setTheme, prefs, setLock)
            } }
        }
    }
}

@Composable private fun V3Drawer(title: String, icon: androidx.compose.ui.graphics.vector.ImageVector, selected: Boolean, click: () -> Unit) = NavigationDrawerItem({ Text(title) }, selected, click, icon = { Icon(icon, null) }, Modifier.padding(horizontal = 10.dp, vertical = 2.dp))
