@Composable private fun V3Home(quick: () -> Unit, deep: () -> Unit, history: () -> Unit) { val stat = remember { v3Storage() }; LazyColumn(Modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) { item { Text("Recover files", style = MaterialTheme.typography.headlineMedium, fontWeight = FontWeight.Bold); Text("Scan your accessible storage and preview recoverable candidates.", color = MaterialTheme.colorScheme.onSurfaceVariant) }; item { Card(Modifier.fillMaxWidth().v3Card(), shape = v3Shape) { Column(Modifier.padding(18.dp)) { Row(verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.SdStorage, null, tint = MaterialTheme.colorScheme.primary); Spacer(Modifier.width(10.dp)); Column(Modifier.weight(1f)) { Text("Internal storage", fontWeight = FontWeight.Bold); Text("${stat.second} used of ${stat.first}", style = MaterialTheme.typography.bodySmall) } Text("${stat.third}%", fontWeight = FontWeight.Bold) }; Spacer(Modifier.height(10.dp)); LinearProgressIndicator({ stat.third / 100f }, Modifier.fillMaxWidth()) } } }; item { Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) { V3ModeCard("Quick Recovery", Icons.Default.FlashOn, Color(0xFFE4A11B), quick, Modifier.weight(1f)); V3ModeCard("Deep Recovery", Icons.Default.Search, Color(0xFF4779E8), deep, Modifier.weight(1f)) } }; item { OutlinedButton(history, Modifier.fillMaxWidth()) { Icon(Icons.Default.History, null); Spacer(Modifier.width(6.dp)); Text("Recovery history") } }; item { Card(Modifier.fillMaxWidth().v3Card(), shape = v3Shape) { Row(Modifier.padding(17.dp), verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.Lock, null, tint = Color(0xFF7B57B5)); Spacer(Modifier.width(10.dp)); Column { Text("Free scan", fontWeight = FontWeight.Bold); Text("Preview is free. Saving recovered files requires Premium.", style = MaterialTheme.typography.bodySmall) } } } } } }
@Composable private fun V3ModeCard(title: String, icon: androidx.compose.ui.graphics.vector.ImageVector, color: Color, click: () -> Unit, modifier: Modifier) { Card(modifier.clickable { click() }.v3Card(), shape = v3Shape) { Column(Modifier.padding(17.dp)) { Box(Modifier.size(46.dp).clip(CircleShape).background(color.copy(.14f)), Alignment.Center) { Icon(icon, null, tint = color) }; Spacer(Modifier.height(10.dp)); Text(title, fontWeight = FontWeight.Bold); Text(if (title.startsWith("Quick")) "Fast media scan" else "Extended media scan", style = MaterialTheme.typography.bodySmall) } } }

@Composable private fun V3Scan(mode: V3Mode, current: List<V3File>, done: (List<V3File>) -> Unit) {
    val context = LocalContext.current; val scope = rememberCoroutineScope(); var running by remember { mutableStateOf(false) }; var paused by remember { mutableStateOf(false) }; var cancelled by remember { mutableStateOf(false) }; var progress by remember { mutableFloatStateOf(0f) }; var found by remember { mutableIntStateOf(0) }; var bytes by remember { mutableLongStateOf(0) }; var elapsed by remember { mutableLongStateOf(0) }; var location by remember { mutableStateOf("Internal storage") }; var minSize by remember { mutableLongStateOf(0) }; var maxSize by remember { mutableLongStateOf(Long.MAX_VALUE) }; var fromDays by remember { mutableIntStateOf(0) }
    val folderLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocumentTree()) { uri -> if (uri != null) { location = "Selected folder"; context.contentResolver.takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION) } }
    fun startScan() { if (running) return; running = true; paused = false; cancelled = false; progress = 0f; found = 0; bytes = 0; elapsed = 0; scope.launch { val start = System.currentTimeMillis(); val result = withContext(Dispatchers.IO) { scanMediaV3(context.contentResolver, mode) }; val total = result.size.coerceAtLeast(1); val filtered = mutableListOf<V3File>(); result.forEachIndexed { index, file -> while (paused && !cancelled) delay(120); if (cancelled) return@forEachIndexed; delay(if (mode == V3Mode.QUICK) 8 else 14); if (file.size >= minSize && file.size <= maxSize && (fromDays == 0 || file.date >= System.currentTimeMillis() - fromDays * 86400000L)) filtered += file; found = index + 1; bytes = filtered.sumOf { it.size }; progress = (index + 1).toFloat() / total; elapsed = System.currentTimeMillis() - start }; running = false; val final = if (cancelled) current else filtered; saveV3History(context.getSharedPreferences("rss_recovery_v3", 0), V3Scan(mode.label, final.size, final.sumOf { it.size }, System.currentTimeMillis(), cancelled)); done(final) } }
    LazyColumn(Modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(13.dp)) { item { Card(Modifier.fillMaxWidth().v3Card(), shape = v3Shape) { Column(Modifier.padding(20.dp)) { Text(mode.label, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold); Text("Only accessible media/files are scanned. Deleted-file recovery depends on device storage access.", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant) } } }; item { V3ScanOption("Location", location) { folderLauncher.launch(null) } }; item { V3FilterCard(minSize, maxSize, fromDays, { minSize = it }, { maxSize = it }, { fromDays = it }) }; item { if (running) Card(Modifier.fillMaxWidth().v3Card(), shape = v3Shape) { Column(Modifier.padding(18.dp)) { val animated by animateFloatAsState(progress, label = "scan"); LinearProgressIndicator({ animated }, Modifier.fillMaxWidth()); Spacer(Modifier.height(10.dp)); Text("${(progress * 100).toInt()}% · $found files · ${v3Bytes(bytes)} · ${elapsed / 1000}s"); Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) { OutlinedButton({ paused = !paused }) { Text(if (paused) "Resume" else "Pause") }; OutlinedButton({ cancelled = true }) { Text("Cancel") } } } } }; item { Button({ startScan() }, Modifier.fillMaxWidth().height(54.dp), enabled = !running) { Text(if (running) "Scanning…" else "Start scan") } } }
}

@Composable private fun V3ScanOption(title: String, value: String, click: () -> Unit) { Card(Modifier.fillMaxWidth().clickable { click() }.v3Card(), shape = v3Shape) { Row(Modifier.padding(16.dp), verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.SdStorage, null, tint = MaterialTheme.colorScheme.primary); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Text(title, fontWeight = FontWeight.SemiBold); Text(value, style = MaterialTheme.typography.bodySmall) }; Icon(Icons.Default.ChevronRight, null) } } }
@Composable private fun V3FilterCard(min: Long, max: Long, days: Int, setMin: (Long) -> Unit, setMax: (Long) -> Unit, setDays: (Int) -> Unit) { var minText by remember(min) { mutableStateOf(if (min == 0L) "" else (min / 1024).toString()) }; var maxText by remember(max) { mutableStateOf(if (max == Long.MAX_VALUE) "" else (max / 1024).toString()) }; Card(Modifier.fillMaxWidth().v3Card(), shape = v3Shape) { Column(Modifier.padding(16.dp)) { Text("Scan filters", fontWeight = FontWeight.Bold); Spacer(Modifier.height(8.dp)); Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) { OutlinedTextField(minText, { minText = it.filter(Char::isDigit); setMin(minText.toLongOrNull()?.times(1024) ?: 0) }, Modifier.weight(1f), label = { Text("Min KB") }, singleLine = true); OutlinedTextField(maxText, { maxText = it.filter(Char::isDigit); setMax(maxText.toLongOrNull()?.times(1024) ?: Long.MAX_VALUE) }, Modifier.weight(1f), label = { Text("Max KB") }, singleLine = true) }; Spacer(Modifier.height(8.dp)); Row(horizontalArrangement = Arrangement.spacedBy(7.dp)) { listOf(0 to "Any date", 1 to "24h", 7 to "7d", 30 to "30d").forEach { (d, label) -> FilterChip(days == d, { setDays(d) }, label = { Text(label) }) } } } } }

@Composable private fun V3Results(files: List<V3File>, destination: Uri?, chooseDestination: () -> Unit, premium: () -> Unit) { var query by remember { mutableStateOf("") }; var type by remember { mutableStateOf("All") }; var sort by remember { mutableStateOf(V3Sort.NAME) }; var selected by remember { mutableStateOf(setOf<String>()) }; var confirm by remember { mutableStateOf(false) }; val visible = files.filter { (query.isBlank() || it.name.contains(query, true)) && (type == "All" || it.type.label == type) }.sortedWith(when(sort) { V3Sort.NAME -> compareBy(String.CASE_INSENSITIVE_ORDER) { it.name }; V3Sort.SIZE -> compareByDescending { it.size }; V3Sort.DATE -> compareByDescending { it.date } }); if (confirm) AlertDialog(onDismissRequest = { confirm = false }, title = { Text("Confirm recovery") }, text = { Text("${selected.size} file(s) selected. Recovery will copy files to your chosen destination. Deleted-file recovery is not guaranteed on non-rooted devices.") }, confirmButton = { TextButton({ confirm = false; premium() }) { Text("Continue to Premium") } }, dismissButton = { TextButton({ confirm = false }) { Text("Cancel") } }); LazyColumn(Modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) { item { OutlinedTextField(query, { query = it }, Modifier.fillMaxWidth(), label = { Text("Search files") }, singleLine = true, leadingIcon = { Icon(Icons.Default.Search, null) }); Spacer(Modifier.height(8.dp)); Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) { listOf("All", "Images", "Videos", "Audio", "Documents").forEach { FilterChip(type == it, { type = it }, label = { Text(it) }) } }; Row(verticalAlignment = Alignment.CenterVertically) { Text("${visible.size} found · ${selected.size} selected", Modifier.weight(1f), style = MaterialTheme.typography.bodySmall); TextButton({ selected = if (selected.size == visible.size) emptySet() else visible.map { it.id }.toSet() }) { Text(if (selected.size == visible.size) "Clear all" else "Select all") } } }; item { Row(horizontalArrangement = Arrangement.spacedBy(7.dp)) { FilterChip(sort == V3Sort.NAME, { sort = V3Sort.NAME }, label = { Text("Name") }); FilterChip(sort == V3Sort.SIZE, { sort = V3Sort.SIZE }, label = { Text("Size") }); FilterChip(sort == V3Sort.DATE, { sort = V3Sort.DATE }, label = { Text("Date") }) } }; items(visible, key = { it.id }) { file -> Card(Modifier.fillMaxWidth().v3Card(), shape = v3Shape) { Row(Modifier.padding(14.dp), verticalAlignment = Alignment.CenterVertically) { Checkbox(selected.contains(file.id), { selected = if (it) selected + file.id else selected - file.id }); Icon(Icons.Default.InsertDriveFile, null, tint = file.type.color); Spacer(Modifier.width(10.dp)); Column(Modifier.weight(1f)) { Text(file.name, fontWeight = FontWeight.SemiBold); Text("${file.type.label} · ${v3Bytes(file.size)}", style = MaterialTheme.typography.bodySmall) }; TextButton({ if (destination == null) chooseDestination() else { selected = setOf(file.id); confirm = true } }) { Text("Recover") } } } }; item { if (selected.isNotEmpty()) Button({ if (destination == null) chooseDestination() else confirm = true }, Modifier.fillMaxWidth().height(52.dp)) { Text("Recover ${selected.size} selected") } } }
}

@Composable private fun V3History(scans: List<V3Scan>) { LazyColumn(Modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) { item { Text("Recovery history", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold) }; if (scans.isEmpty()) item { Text("No scans yet. Start a scan to build your history.", color = MaterialTheme.colorScheme.onSurfaceVariant) }; items(scans) { s -> Card(Modifier.fillMaxWidth().v3Card(), shape = v3Shape) { Column(Modifier.padding(16.dp)) { Text(s.mode, fontWeight = FontWeight.Bold); Text("${s.count} files · ${v3Bytes(s.bytes)}", style = MaterialTheme.typography.bodySmall); Text(DateFormat.getDateTimeInstance().format(Date(s.date)), style = MaterialTheme.typography.bodySmall); if (s.cancelled) Text("Cancelled", color = MaterialTheme.colorScheme.error) else Text("Completed", color = Color(0xFF20A66A)) } } } } }
@Composable private fun V3Premium() { LazyColumn(Modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) { item { Card(Modifier.fillMaxWidth().v3Card(), shape = RoundedCornerShape(24.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer)) { Column(Modifier.padding(23.dp)) { Icon(Icons.Default.WorkspacePremium, null, Modifier.size(48.dp), tint = Color(0xFFE0A31B)); Text("Premium recovery", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold); Spacer(Modifier.height(8.dp)); Text("Unlock saving and advanced recovery protection.") } } }; items(listOf("Save selected files", "Advanced scan filters", "Recovery destination control", "Original filename when available", "Metadata preservation", "Recovery history")) { FeatureV3(it) } } }
@Composable private fun FeatureV3(text: String) { Card(Modifier.fillMaxWidth().v3Card(), shape = v3Shape) { Row(Modifier.padding(16.dp), verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.CheckCircle, null, tint = Color(0xFF20A66A)); Spacer(Modifier.width(10.dp)); Text(text, fontWeight = FontWeight.SemiBold) } } }

@Composable private fun V3Settings(dark: Boolean, setDark: (Boolean) -> Unit, theme: Int, setTheme: (Int) -> Unit, prefs: android.content.SharedPreferences, setLock: (Boolean) -> Unit) { var pinDialog by remember { mutableStateOf(false) }; var haptic by remember { mutableStateOf(prefs.getBoolean("haptic", true)) }; var notifications by remember { mutableStateOf(prefs.getBoolean("notifications", true)) }; if (pinDialog) V3PinDialog({ pin -> prefs.edit().putString("pin", pin).putBoolean("lock", true).apply(); setLock(true); pinDialog = false }, { pinDialog = false }); LazyColumn(Modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) { item { Text("Settings", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold) }; item { V3SettingGroup("Appearance") { Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) { FilterChip(!dark, { setDark(false) }, label = { Text("Light") }); FilterChip(dark, { setDark(true) }, label = { Text("Dark") }) } } }; item { V3SettingGroup("Color theme") { v3Themes.forEachIndexed { i, pair -> Card(Modifier.fillMaxWidth().padding(vertical = 3.dp).clickable { setTheme(i) }, shape = v3Shape, colors = CardDefaults.cardColors(containerColor = pair.second)) { Row(Modifier.padding(14.dp), verticalAlignment = Alignment.CenterVertically) { Box(Modifier.size(27.dp).clip(CircleShape).background(pair.first)); Spacer(Modifier.width(12.dp)); Text(listOf("Royal Gold", "Ocean", "Emerald", "Plum")[i], Modifier.weight(1f), fontWeight = FontWeight.SemiBold); if (theme == i) Icon(Icons.Default.Check, null, tint = pair.first) } } } } }; item { V3SettingGroup("Security") { Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.Lock, null, tint = Color(0xFF7B57B5)); Spacer(Modifier.width(12.dp)); Text("App Lock", Modifier.weight(1f), fontWeight = FontWeight.SemiBold); Switch(prefs.getBoolean("lock", false), { if (it) pinDialog = true else { prefs.edit().remove("pin").putBoolean("lock", false).apply(); setLock(false) } }) } } }; item { V3SettingGroup("Experience") { Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) { Text("Haptic feedback", Modifier.weight(1f)); Switch(haptic, { haptic = it; prefs.edit().putBoolean("haptic", it).apply() }) }; Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) { Text("Notifications", Modifier.weight(1f)); Switch(notifications, { notifications = it; prefs.edit().putBoolean("notifications", it).apply() }) } } }; item { V3SettingGroup("Privacy & safety") { Text("Scans use only storage that Android grants the app access to. The app does not promise recovery of every deleted file; device, filesystem and permissions affect results.", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant) } } }
}
@Composable private fun V3SettingGroup(title: String, content: @Composable ColumnScope.() -> Unit) { Column { Text(title, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold); Spacer(Modifier.height(7.dp)); Card(Modifier.fillMaxWidth().v3Card(), shape = v3Shape) { Column(Modifier.padding(15.dp), content = content) } } }
@Composable private fun V3PinDialog(done: (String) -> Unit, cancel: () -> Unit) { var pin by remember { mutableStateOf("") }; AlertDialog(onDismissRequest = cancel, title = { Text("Set app PIN") }, text = { OutlinedTextField(pin, { if (it.length <= 6 && it.all(Char::isDigit)) pin = it }, label = { Text("4–6 digits") }, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.NumberPassword), singleLine = true) }, confirmButton = { TextButton({ done(pin) }, enabled = pin.length in 4..6) { Text("Save") } }, dismissButton = { TextButton(cancel) { Text("Cancel") } }) }
@Composable private fun V3Lock(unlock: (String) -> Unit) { var pin by remember { mutableStateOf("") }; Box(Modifier.fillMaxSize(), Alignment.Center) { Column(Modifier.padding(24.dp), horizontalAlignment = Alignment.CenterHorizontally) { Icon(Icons.Default.Lock, null, Modifier.size(60.dp), tint = MaterialTheme.colorScheme.primary); Text("App locked", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold); Spacer(Modifier.height(16.dp)); OutlinedTextField(pin, { if (it.length <= 6 && it.all(Char::isDigit)) pin = it }, label = { Text("PIN") }, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.NumberPassword), singleLine = true); Spacer(Modifier.height(12.dp)); Button({ unlock(pin) }, enabled = pin.length >= 4) { Text("Unlock") } } } }
@Composable private fun V3DestinationDialog(done: (Uri) -> Unit, cancel: () -> Unit) { AlertDialog(onDismissRequest = cancel, title = { Text("Choose recovery destination") }, text = { Text("Choose a folder with Android's system picker. The selected folder is used as the recovery destination.") }, confirmButton = { TextButton({ cancel() }) { Text("Choose from scan screen") } }, dismissButton = { TextButton(cancel) { Text("Close") } }) }

private suspend fun scanMediaV3(resolver: ContentResolver, mode: V3Mode): List<V3File> = withContext(Dispatchers.IO) { val out = mutableListOf<V3File>(); val collections = listOf(MediaStore.Images.Media.EXTERNAL_CONTENT_URI to V3Type.IMAGE, MediaStore.Video.Media.EXTERNAL_CONTENT_URI to V3Type.VIDEO, MediaStore.Audio.Media.EXTERNAL_CONTENT_URI to V3Type.AUDIO, MediaStore.Files.getContentUri("external") to V3Type.OTHER); collections.forEach { (uri, type) -> resolver.query(uri, arrayOf(MediaStore.MediaColumns._ID, MediaStore.MediaColumns.DISPLAY_NAME, MediaStore.MediaColumns.SIZE, MediaStore.MediaColumns.DATE_MODIFIED), null, null, "${MediaStore.MediaColumns.DATE_MODIFIED} DESC")?.use { c -> val id = c.getColumnIndexOrThrow(MediaStore.MediaColumns._ID); val name = c.getColumnIndexOrThrow(MediaStore.MediaColumns.DISPLAY_NAME); val size = c.getColumnIndexOrThrow(MediaStore.MediaColumns.SIZE); val date = c.getColumnIndexOrThrow(MediaStore.MediaColumns.DATE_MODIFIED); while(c.moveToNext()) { val n = c.getString(name) ?: continue; val s = c.getLong(size); val d = c.getLong(date) * 1000; val itemUri = Uri.withAppendedPath(uri, c.getLong(id).toString()); if (s >= 0) out += V3File(itemUri.toString(), n, type, s, d, itemUri) } } } }; if (mode == V3Mode.QUICK) out.take(300) else out.take(1500) }
private fun v3Storage(): Triple<String,String,Int> { val path = Environment.getDataDirectory().path; val stat = StatFs(path); val total = stat.totalBytes; val free = stat.availableBytes; val used = total - free; val pct = if (total == 0L) 0 else ((used * 100) / total).toInt(); return Triple(v3Bytes(total), v3Bytes(used), pct) }
private fun v3Bytes(value: Long): String { if (value < 1024) return "$value B"; val units = arrayOf("KB","MB","GB","TB"); var v = value.toDouble(); var i = -1; while(v >= 1024 && i < units.lastIndex) { v /= 1024; i++ }; return String.format(Locale.US, "%.1f %s", v, units[i]) }
private fun loadV3History(prefs: android.content.SharedPreferences): List<V3Scan> { val raw = prefs.getStringSet("history", emptySet()) ?: emptySet(); return raw.mapNotNull { val p = it.split('|'); if (p.size >= 4) V3Scan(p[0], p[1].toIntOrNull() ?: 0, p[2].toLongOrNull() ?: 0, p[3].toLongOrNull() ?: 0, p.getOrNull(4) == "1") else null }.sortedByDescending { it.date }.take(20) }
private fun saveV3History(prefs: android.content.SharedPreferences, scan: V3Scan) { val set = (prefs.getStringSet("history", emptySet()) ?: emptySet()).toMutableSet(); set += "${scan.mode}|${scan.count}|${scan.bytes}|${scan.date}|${if (scan.cancelled) 1 else 0}"; prefs.edit().putStringSet("history", set.takeLast(20).toSet()).apply() }
private fun dialV3(context: Context, number: String) { context.startActivity(Intent(Intent.ACTION_DIAL, Uri.parse("tel:$number"))) }
private fun openV3(uri: String) { }
